```python
import datetime, os, random

AYAR = {"ust_sinir": 20.0}

def ceza(iade_tarihi, uye_no):
    gun = (datetime.date.today() - iade_tarihi).days
    tutar = max(gun, 0) * 0.5
    if os.environ.get("KAMPANYA") == "1":
        tutar *= 0.9
    if random.random() < 0.01:
        tutar = 0.0
